	allegiance = "Réprouvés",
	aliases = { "Morbin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Morbin Lightbane est un paladin réprouvé. Il croit que son devoir est double : accomplir la volonté de {link:sylvanas-windrunner}la Dame noire{/link} et subvenir aux besoins de son peuple. Au-dessus d'{link:undercity}Undercity{/link}, le {link:scourge}Fléau{/link} erre encore en grand nombre dans les ruines, et les {link:forsaken}Réprouvés{/link} qui le combattent tombent. La chair en décomposition ne guérit pas d'elle-même. Morbin rassemble des membres entiers sur les morts tombés, afin que ses frères et sœurs puissent être réparés.]=],
		},
		{
