			text = [=[Morbin garde vivante la mémoire de {link:garek-bandarion}Garek Bandarion{/link}, qu'il appelle le glorieux capitaine. Il croit que Garek aurait voulu que les ruines soient reprises et les siens soignés. Ceux qui apportent à Morbin ce dont il a besoin, dit-il, font honneur à leur capitaine.]=],
		},
	},
	mentions = {
		{ text = "La justice de la Lumière" },
	},
	bonds = {
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "le capitaine qu'il honore" },
	},
})
